// Né là-bas — événements, décisions, pauses.
// Format : { id, a:[min,max], t:['GLP',...] (territoires, optionnel), c:()=>cond, w:poids, once, gap, run:()=>texte|{t,k,f} }
// k : 'ev' neutre, 'good', 'bad', 'loss' (deuil). f : fait sourcé affiché sous la ligne.
import { S, C, TBY, eff, log, chance, pick, ri, rnd, clamp, incomeAt, JOBS, WORKING, lifeTable, makeName, die, aVille, jobWeight, wpick, JOB_PUB, varied, retire as E_retire, JOB_NEXT, JOB_CS, CS_RANK, jobName, lycees, CPGE, HEX, hexRegionW, CAUSE, pickCause, skinOfPartner, kidSkin, toInt, mensualite, eurMois } from './engine.js';

const fem = () => S.sex === 'F';
